//! Typst translation data modules for a Typst rendering runtime.

/// Typst output destinations.
pub mod config;

pub use config::OutputConfig;
pub use globetrotter_model::json::Error;
use globetrotter_model::{Language, TemplateEngine, Translations, json};

/// Generates a Typst module with the translation data and per-key argument types.
///
/// The module exports `version`, `engine`, `languages`, `arguments`, and `translations`; the
/// header of the generated file describes their shapes.
/// Templates stay unrendered source strings, like in the JSON output, so a Typst runtime that
/// imports the module renders them and validates calls against `arguments`.
///
/// # Errors
///
/// Returns [`Error::MissingKey`] when `strict` is set and a key has no translation in one of
/// `languages`.
/// Without `strict`, a missing translation becomes the same placeholder literal as in the
/// JSON output.
pub fn generate_module(
    translations: &Translations,
    engine: Option<&TemplateEngine>,
    languages: &[Language],
    strict: bool,
) -> Result<String, Error> {
    // The JSON output's version string, such as "1", is also a valid Typst string literal.
    let version = serde_json::to_string(&json::Version::default())?;
    let engine = engine.map_or_else(|| "none".to_string(), |engine| string(&engine.to_string()));

    // A one-element Typst array needs a trailing comma.
    let language_codes = match languages {
        [language] => format!("{},", string(language.code())),
        languages => languages
            .iter()
            .map(|language| string(language.code()))
            .collect::<Vec<_>>()
            .join(", "),
    };

    let arguments = translations.iter().map(|(key, translation)| {
        let arguments = translation
            .arguments
            .iter()
            .map(|(name, typ)| format!("{}: {}", string(name), string(&typ.to_string())))
            .collect::<Vec<_>>();
        let arguments = if arguments.is_empty() {
            "(:)".to_string()
        } else {
            format!("({})", arguments.join(", "))
        };
        format!("{}: {arguments}", string(key))
    });

    let mut catalog = Vec::with_capacity(languages.len());
    for language in languages {
        let entries = translations
            .translations_json(*language, None, strict)?
            .translations
            .into_iter()
            .map(|(key, translation)| {
                let (json::Translation::Literal(source) | json::Translation::Template(source)) =
                    translation;
                format!("{}: {}", string(&key), string(&source))
            });
        catalog.push(format!(
            "{}: {}",
            string(language.code()),
            dictionary(entries, "  ")
        ));
    }

    Ok(format!(
        "// AUTOGENERATED. DO NOT EDIT.\n\
         // Generated by globetrotter v{generator}.\n\
         //\n\
         {header}\n\
         #let version = {version}\n\n\
         #let engine = {engine}\n\n\
         #let languages = ({language_codes})\n\n\
         #let arguments = {arguments}\n\n\
         #let translations = {catalog}\n",
        generator = env!("CARGO_PKG_VERSION"),
        header = include_str!("header.typ"),
        arguments = dictionary(arguments, ""),
        catalog = dictionary(catalog, ""),
    ))
}

/// Formats a Typst dictionary literal with one entry per line.
fn dictionary(entries: impl IntoIterator<Item = String>, indent: &str) -> String {
    let entries = entries
        .into_iter()
        .map(|entry| format!("{indent}  {entry},\n"))
        .collect::<Vec<_>>();
    if entries.is_empty() {
        "(:)".to_string()
    } else {
        format!("(\n{}{indent})", entries.concat())
    }
}

/// Formats `value` as a Typst string literal.
fn string(value: &str) -> String {
    let mut literal = String::with_capacity(value.len() + 2);
    literal.push('"');
    for character in value.chars() {
        match character {
            '"' => literal.push_str("\\\""),
            '\\' => literal.push_str("\\\\"),
            '\n' => literal.push_str("\\n"),
            '\r' => literal.push_str("\\r"),
            '\t' => literal.push_str("\\t"),
            // Rust's `\u{1}` escape form is also Typst's.
            character if character.is_control() => literal.extend(character.escape_unicode()),
            character => literal.push(character),
        }
    }
    literal.push('"');
    literal
}
